package com.app.entity;
import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="society_daily_checklist_entries") @Data @Builder @NoArgsConstructor @AllArgsConstructor
public class SocietyDailyChecklistEntry {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="account_id",nullable=false) private Account account; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="template_id",nullable=false) private SocietyDailyChecklistTemplate template; @Column(nullable=false) private LocalDate operationDate; @Column(nullable=false) @Builder.Default private Boolean completed=false; @Column(length=1000) private String notes; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="completed_by_user_id") private User completedBy; private LocalDateTime completedAt; @Column(nullable=false,updatable=false) @Builder.Default private LocalDateTime createdAt=LocalDateTime.now(); @Column(nullable=false) @Builder.Default private LocalDateTime updatedAt=LocalDateTime.now(); @PreUpdate void touch(){updatedAt=LocalDateTime.now();}}
